<?php
namespace App\Models;
use Illuminate\Foundation\Auth\User as Authenticatable;use Illuminate\Notifications\Notifiable;use Illuminate\Database\Eloquent\SoftDeletes;use Laravel\Sanctum\HasApiTokens;
class User extends Authenticatable{use HasApiTokens,Notifiable,SoftDeletes;protected $table='users';protected $primaryKey='user_id';protected $guarded=[];protected $hidden=['password','remember_token'];protected $casts=['password'=>'hashed','email_verified_at'=>'datetime','last_login_at'=>'datetime','is_active'=>'boolean'];public function person(){return $this->belongsTo(Person::class,'person_id','person_id');}public function roles(){return $this->belongsToMany(Role::class,'user_roles','user_id','role_id')->withTimestamps();}public function employee(){return $this->hasOne(Employee::class,'user_id','user_id');}public function customer(){return $this->hasOne(Customer::class,'user_id','user_id');}public function hasRole(string $slug):bool{return $this->roles()->where('slug',$slug)->exists();}public function hasAnyRole(array $slugs):bool{return $this->roles()->whereIn('slug',$slugs)->exists();}public function hasPermission(string $slug):bool{return $this->roles()->whereHas('permissions',fn($q)=>$q->where('slug',$slug))->exists();}}
